window.PLACES_DATA.forEach((p, i) => {
  p.id = "p" + i;
  const q = encodeURIComponent(p.name + ", " + p.address);
  // không có origin => Google Maps tự lấy vị trí hiện tại của máy
  p.mapsUrl = "https://www.google.com/maps/search/?api=1&query=" + q + "&query_place_id=" + p.pid;
  p.dirUrl = "https://www.google.com/maps/dir/?api=1&destination=" + q + "&destination_place_id=" + p.pid;
});

// Điểm "làm việc" của quán cà phê: chỉ quán ghi rõ là chỗ học / làm việc mới được điểm cao.
// Quán có chủ đề khác (gốm, tô tượng, board game, mèo, nằm, rooftop, bánh, trà sữa...) bị hạ hẳn
// và không hiện khi anh chọn gu "Làm việc".
window.WORK_YES = /study|workspace|working|co\.?-?working|làm việc|học bài|học tập|focus|library|thư viện|deadline|meeting room|24h|24\/24|24\/7/i;
window.WORK_NO = /beer|pub|gốm|tô tượng|pottery|vẽ|painting|board ?game|poker|mèo|catfe|in bed|giấc|nap cafe|rooftop|kem|chè|trà sữa|milk tea|dessert|patisserie|bánh|bakes|bakery|dimsum|trà san|hong kong|trứng|egg|thuốc lào|vợt|souvenir|sân vườn|koi fish|biệt thự|villa|view/i;
window.PLACES_DATA.forEach((p) => {
  if (p.type !== "cafe") return;
  const t = p.name + " | " + p.cat;
  const w = p.gu.work;
  if (window.WORK_YES.test(t)) p.gu.work = 9;
  else if (window.WORK_NO.test(t)) {
    p.gu.work = Math.min(w, 3);
    p.verdict = p.verdict.replace("khi tìm cafe làm việc", "khi tìm cafe");
  } else p.gu.work = w >= 8 ? 6 : Math.min(w, 5);
});

// Android: gọi thẳng app bản đồ của máy (geo: / google.navigation:), không phụ thuộc trình duyệt.
// Nếu 1,5 giây sau trang vẫn còn hiện (máy không mở được app) thì mở bản web.
window.PLACES_DATA.forEach((p) => {
  const q = encodeURIComponent(p.name + ", " + p.address);
  p.geoUrl = "geo:0,0?q=" + q;
  p.navUrl = "google.navigation:q=" + q;
});
const IS_ANDROID = /Android/i.test(navigator.userAgent);
window.mapLink = (url, app) => IS_ANDROID
  ? 'href="' + url + '" data-app="' + app + '"'
  : 'target="_blank" rel="noopener" href="' + url + '"';
document.addEventListener("click", (e) => {
  const a = e.target.closest && e.target.closest("a[data-app]");
  if (!a) return;
  e.preventDefault();
  const web = a.href;
  location.href = a.dataset.app;
  setTimeout(() => { if (!document.hidden) location.href = web; }, 1500);
});
